const ov = await sdk.static.inspectWasm({view:"overview",startLine:1,lineCount:10});
const fl = await sdk.static.listFunctions({startIndex:0,limit:30});
let excerpt=null;
let pick = 0;
for (const f of fl.functions||[]) { if ((f.exportName||"").toLowerCase().includes("update")) { pick=f.index; break; } }
if (!pick && fl.functions && fl.functions.length) pick = fl.functions[0].index;
const fi = await sdk.static.inspectFunction({functionIndex:pick,startLine:1,lineCount:100});
excerpt={pick, lines:(fi.wat||"").slice(0,1500)};
const dc = await sdk.static.decompileFunction({functionIndex:pick,startLine:1,lineCount:60});
const cp = await sdk.prepareCheckpoint({hypothesis:"reach gameplay for dash test", steps:[{buttons:1,frames:10,checkpoint:"title-press"},{buttons:0,frames:30,checkpoint:"gameplay"}], watches:[]});
const exp = await sdk.runExperiment({hypothesis:"X press triggers dash displacement vs no press", checkpointId: cp.checkpointId, interventions:[], steps:{buttons:1,frames:30,checkpoint:"dash-window"}, observations:{channels:["motion","timers","events"],watches:[],captures:[]}});
const exp2 = await sdk.runExperiment({hypothesis:"baseline no input drift", checkpointId: cp.checkpointId, interventions:[], steps:{buttons:0,frames:30,checkpoint:"idle-window"}, observations:{channels:["motion","timers","events"],watches:[],captures:[]}});
return {overview:{imports:(ov.imports||[]).length, exports:ov.exports||[]}, funcCount: fl.totalCount||fl.functions.length, excerptPick: excerpt.pick, excerptText: excerpt.lines, decomp:(dc.pseudo||"").slice(0,1500), cpId: cp.checkpointId, expArtifact: exp.artifactId, exp2Artifact: exp2.artifactId, expSummary: JSON.stringify(exp.summary||exp).slice(0,2000), exp2Summary: JSON.stringify(exp2.summary||exp2).slice(0,2000)};

const ov = await sdk.static.inspectWasm({view:"overview",startLine:1,lineCount:10});
const fl = await sdk.static.listFunctions({startIndex:0,limit:30});
let pick=0; try{ for(const f of (fl.functions||fl.list||[])){ const n=((f.exportName||"")+" "+(f.name||"")).toLowerCase(); if(n.includes("update")){pick=f.index;break;} } if(!pick){ const a=(fl.functions||fl.list||[])[0]; if(a) pick=a.index||0; } }catch(e){}
const fi = await sdk.static.inspectFunction({functionIndex:pick,startLine:1,lineCount:80});
const dc = await sdk.static.decompileFunction({functionIndex:pick,startLine:1,lineCount:50});
const cp = await sdk.prepareCheckpoint({hypothesis:"reach gameplay", steps:[{buttons:1,frames:10,checkpoint:"title-press"},{buttons:0,frames:30,checkpoint:"gameplay"}], watches:[]});
const e1 = await sdk.runExperiment({hypothesis:"X triggers dash vs idle", checkpointId:cp.checkpointId, interventions:[], steps:[{buttons:1,frames:30,checkpoint:"dash-win"}], observations:{channels:["motion","timers","events"],watches:[],captures:[]}});
const e2 = await sdk.runExperiment({hypothesis:"idle baseline", checkpointId:cp.checkpointId, interventions:[], steps:[{buttons:0,frames:30,checkpoint:"idle-win"}], observations:{channels:["motion","timers","events"],watches:[],captures:[]}});
return {exp:ov.exports||ov, n:JSON.stringify(fl).slice(0,800), pick, wat:JSON.stringify(fi).slice(0,1800), pseudo:JSON.stringify(dc).slice(0,1500), cp:cp.checkpointId, a1:e1.artifactId, a2:e2.artifactId, s1:JSON.stringify(e1.summary||e1).slice(0,1800), s2:JSON.stringify(e2.summary||e2).slice(0,1800)};

